using System;
using System.Threading;
using Xunit;
using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to isolate tests
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain again after test
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_FourParams_EnqueuesNotification()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("Student (ID: 1)", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_FiveParams_WithDisplayName_EnqueuesNotification()
        {
            _service.SendNotification("Course", "42", "Chemistry", EntityOperation.UPDATE, "AdminUser");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("Course 'Chemistry'", notification.Message);
            Assert.Contains("updated", notification.Message);
            Assert.Equal("AdminUser", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            _service.SendNotification("Dept", "1", null, EntityOperation.CREATE, null);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _service.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleItems_ReturnsFIFO()
        {
            _service.SendNotification("A", "1", EntityOperation.CREATE);
            _service.SendNotification("B", "2", EntityOperation.UPDATE);
            _service.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();
            var third = _service.ReceiveNotification();
            var fourth = _service.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
            Assert.Null(fourth);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_AllOperations_GenerateCorrectMessage(EntityOperation operation, string expectedWord)
        {
            _service.SendNotification("Entity", "1", "TestEntity", operation);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains(expectedWord, notification.Message);
            Assert.Contains("TestEntity", notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        [Fact]
        public void GenerateMessage_WithoutDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Student", "99", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();

            Assert.Contains("Student (ID: 99)", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void GenerateMessage_WithEmptyDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Student", "99", "   ", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.Contains("Student (ID: 99)", notification.Message);
        }

        [Fact]
        public void GenerateMessage_WithDisplayName_UsesNameFormat()
        {
            _service.SendNotification("Course", "1050", "Chemistry", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.Equal("New Course 'Chemistry' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_CreatedAt_IsRecentTimestamp()
        {
            var before = DateTime.Now.AddSeconds(-1);
            _service.SendNotification("Test", "1", EntityOperation.CREATE);
            var after = DateTime.Now.AddSeconds(1);

            var notification = _service.ReceiveNotification();

            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op, just verify it doesn't throw
