using System;
using System.IO;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly CoursesController _controller;
        private readonly string _tempPath;

        public CoursesControllerTests()
        {
            _context = TestHelper.CreateContext();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _tempPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempPath);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempPath);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempPath);
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { Directory.Delete(_tempPath, true); } catch { }
        }

        private Department SeedDepartment()
        {
            var dept = new Department { Name = "Engineering", Budget = 350000, StartDate = new DateTime(2007, 9, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(Department dept = null)
        {
            dept ??= SeedDepartment();
            var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // ---- Index tests ----

        [Fact]
        public void Index_ReturnsCoursesWithDepartment()
        {
            var dept = SeedDepartment();
            SeedCourse(dept);

            var result = _controller.Index() as ViewResult;
            var model = result.Model as System.Collections.Generic.List<Course>;

            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Chemistry", model[0].Title);
            Assert.NotNull(model[0].Department);
            Assert.Equal("Engineering", model[0].Department.Name);
        }

        // ---- Details tests ----

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsCourseWithDepartment()
        {
            var dept = SeedDepartment();
            SeedCourse(dept);

            var result = _controller.Details(1050) as ViewResult;
            var model = result.Model as Course;

            Assert.NotNull(model);
            Assert.Equal("Chemistry", model.Title);
            Assert.Equal(3, model.Credits);
            Assert.NotNull(model.Department);
        }

        // ---- Create GET tests ----

        [Fact]
        public void Create_Get_PopulatesDepartmentSelectList()
        {
            SeedDepartment();

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(result.ViewData["DepartmentID"]);
        }

        // ---- Create POST tests ----

        [Fact]
        public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "New Course", Credits = 3, DepartmentID = dept.DepartmentID };

            var result = _controller.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(1, _context.Courses.Count());
            Assert.Equal("New Course", _context.Courses.First().Title);
        }

        [Fact]
        public void Create_Post_InvalidExtension_ReturnsViewWithError()
        {
            SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Test", Credits = 3, DepartmentID = 1 };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("document.pdf");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage;
            Assert.Contains("valid image file", error);
        }

        [Fact]
        public void Create_Post_FileTooLarge_ReturnsViewWithError()
        {
            SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Test", Credits = 3, DepartmentID = 1 };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("image.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage;
            Assert.Contains("5MB", error);
        }

        [Fact]
        public void Create_Post_ValidFile_SavesAndRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("photo.png");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = _context.Courses.First();
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
            Assert.Contains(".png", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Test", Credits = 3, DepartmentID = 1 };
            _controller.ModelState.AddModelError("Title", "Required");

            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Courses);
        }

        // ---- Edit GET tests ----

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
