        [Fact]
        public void Delete_Get_ValidId_ReturnsView()
        {
            SeedCourse();

            var result = _controller.Delete(1050) as ViewResult;
            var model = result.Model as Course;

            Assert.NotNull(model);
            Assert.Equal("Chemistry", model.Title);
        }

        // ---- DeleteConfirmed tests ----

        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            SeedCourse();

            var result = _controller.DeleteConfirmed(1050) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Empty(_context.Courses);
        }

        [Fact]
        public void DeleteConfirmed_WithImage_DeletesImageFile()
        {
            var dept = SeedDepartment();
            // Create a fake image file
            var uploadsPath = Path.Combine(_tempPath, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsPath);
            var imagePath = Path.Combine(uploadsPath, "test.jpg");
            File.WriteAllText(imagePath, "fake image");

            var course = new Course
            {
                CourseID = 3000,
                Title = "WithImage",
