using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestHelper.CreateContext();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
        }

        private (Instructor instructor, Department dept, Course course) SeedFullData()
        {
            var instructor = new Instructor
            {
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>()
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var ca = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            _context.CourseAssignments.Add(ca);
            _context.SaveChanges();

            return (instructor, dept, course);
        }

        // ---- Index tests ----

        [Fact]
        public void Index_NoSelection_ReturnsAllInstructors()
        {
            SeedFullData();

            var result = _controller.Index(null, null) as ViewResult;
            var model = result.Model as InstructorIndexData;

            Assert.NotNull(model);
            Assert.Single(model.Instructors);
            Assert.Null(model.Courses);
            Assert.Null(model.Enrollments);
        }

        [Fact]
        public void Index_WithInstructorSelected_ReturnsCourses()
        {
            var (instructor, _, _) = SeedFullData();

            var result = _controller.Index(instructor.ID, null) as ViewResult;
            var model = result.Model as InstructorIndexData;

            Assert.NotNull(model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Chemistry", model.Courses.First().Title);
        }

        [Fact]
        public void Index_WithCourseSelected_ReturnsEnrollments()
        {
            var (instructor, _, course) = SeedFullData();

            // Add an enrollment
            var student = new Student { LastName = "Test", FirstMidName = "S", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            _context.SaveChanges();

            var enrollment = new Enrollment { CourseID = course.CourseID, StudentID = student.ID, Grade = Grade.A };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var result = _controller.Index(instructor.ID, course.CourseID) as ViewResult;
            var model = result.Model as InstructorIndexData;

            Assert.NotNull(model);
            Assert.NotNull(model.Enrollments);
            Assert.Single(model.Enrollments);
        }

        // ---- Details tests ----

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructor()
        {
            var (instructor, _, _) = SeedFullData();

            var result = _controller.Details(instructor.ID) as ViewResult;
            var model = result.Model as Instructor;

            Assert.NotNull(model);
            Assert.Equal("Smith", model.LastName);
            Assert.Equal("John", model.FirstMidName);
        }

        // ---- Create GET tests ----

        [Fact]
        public void Create_Get_ReturnsViewWithInstructor()
        {
            // Seed a course so PopulateAssignedCourseData has data
            var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
