public void HasNextPage_OnLastPage_ReturnsFalse()
{
    // 10 items, page size 5, page 2 = last page
    var list = new PaginatedList<int>(new List<int> { 6 }, 10, 2, 5);
    Assert.False(list.HasNextPage);
}

